    50→static inline void wdt_ll_set_period(wdt_hw_t *hw, uint32_t period)
    51→{
    52→#if CONFIG_NMI_WDT_EN
    53→	uint32_t nmi_wdt_clk_div = sys_hal_nmi_wdt_get_clk_div();
    54→
    55→	uint32_t multi = 1;
    56→	switch(nmi_wdt_clk_div) {
    57→	case 0:  //wdt_clk = src_clk/2
    58→		multi = 16;
    59→		break;
    60→	case 1:  //wdt_clk = src_clk/4
    61→		multi = 8;
    62→		break;
    63→	case 2:  //wdt_clk = src_clk/8
    64→		multi = 4;
    65→		break;
    66→	case 3:  //wdt_clk = src_clk/16
    67→		multi = 2;
    68→		break;
    69→	default:
    70→		multi = 1;
    71→		break;
    72→	}
    73→
    74→	period = period * multi;
    75→	if (period > WDT_F_PERIOD_M) {
    76→		period = WDT_F_PERIOD_M;
    77→	}
    78→#endif
    79→
    80→	hw->global_ctrl.soft_reset = 1;
    81→
    82→	uint32_t ctrl_val = (period & WDT_F_PERIOD_M) | (WDT_V_KEY_1ST << WDT_F_KEY_S);
    83→	REG_WRITE(WDT_R_CTRL, ctrl_val);
    84→
    85→	ctrl_val = (period & WDT_F_PERIOD_M) | (WDT_V_KEY_2ND << WDT_F_KEY_S);
    86→	REG_WRITE(WDT_R_CTRL, ctrl_val);
    87→}
